import numpy as np
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt
from rdkit import Chem
D=np.load('model.npz'); X=D['xyz']; syms=D['syms']; ag=int(D['ag']);
ms=[Chem.AddHs(Chem.MolFromSmiles(s)) for s in ['Cc1cc(O[Si](C)C)nc2c(C)cccc12','P(C1CCCCC1)(C1CCCCC1)C1CCCCC1','[O-]S(=O)(=O)C(F)(F)F']]
b=[];i=0
for m in ms:
 for q in m.GetBonds():b.append((q.GetBeginAtomIdx()+i,q.GetEndAtomIdx()+i))
 i+=m.GetNumAtoms()
b += [(92,j) for j in [5,8,32,84,93,ag]]
colors={'H':'#cccccc','C':'#444444','N':'#2255cc','O':'red','Si':'orange','Rh':'purple','P':'#dd7700','F':'green','S':'#cccc00'}
fig=plt.figure(figsize=(15,7))
for n,(el,az) in enumerate([(75,-90),(25,-70)]):
 ax=fig.add_subplot(1,2,n+1,projection='3d')
 for a,c in b:
  ax.plot(*X[[a,c]].T,color='gray',lw=1.2)
 for i,s in enumerate(syms):
  ax.scatter(*X[i],color=colors[s],s=28 if s=='H' else 70)
  if s not in ['H','C'] or i in [11,ag]: ax.text(*X[i],f'{s}{i}',fontsize=9)
 ax.set_box_aspect([1,1,1]); ax.view_init(elev=el,azim=az)
plt.savefig('render.png',dpi=140)
